{!REQUIRESCRIPT("/soap/ajax/40.0/connection.js")}
var objCase = new sforce.SObject('Case');
objCase.Id = '{!Case.Id}';
objCase.OwnerId = "{!$User.Id}";
objCase.Status = 'Closed - Resolved';
var result = sforce.connection.update([objCase]);
if(result[0].success=='true'){
location.reload(true);}
objCase.Status = 'Pending Info from Customer';
var result = sforce.connection.update([objCase]);
if(result[0].success=='true'){
location.reload(true);}
